package com.andye.warmod.phalanx;import com.andye.warmod.block.entity.PhalanxBlockEntity;import java.util.*;import net.fabricmc.fabric.api.event.lifecycle.v1.*;import net.minecraft.server.level.ServerLevel;
public final class PhalanxManager{private static final Map<ServerLevel,Map<UUID,PhalanxBlockEntity>> ACTIVE=new WeakHashMap<>();private static boolean registered;private PhalanxManager(){}public static void registerLifecycle(){if(registered)return;ServerLifecycleEvents.SERVER_STOPPED.register(s->{ACTIVE.clear();PhalanxChunkTicketManager.clear();});registered=true;}public static synchronized boolean canPlace(ServerLevel level){return ACTIVE.getOrDefault(level,Map.of()).size()<PhalanxConstants.MAX_TURRETS_PER_LEVEL;}public static synchronized boolean register(ServerLevel level,PhalanxBlockEntity turret){if(!canPlace(level)||!PhalanxChunkTicketManager.register(level,turret.turretId(),turret.getBlockPos()))return false;ACTIVE.computeIfAbsent(level,x->new LinkedHashMap<>()).put(turret.turretId(),turret);return true;}public static synchronized void unregister(ServerLevel level,PhalanxBlockEntity turret){PhalanxChunkTicketManager.unregister(level,turret.turretId());var m=ACTIVE.get(level);if(m!=null){m.remove(turret.turretId());if(m.isEmpty())ACTIVE.remove(level);}}}

